                continue
            stack = [(r, c)]
            seen.add((r, c))
            obj = []
            while stack:
                y, x = stack.pop()
                obj.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            # Recolor objects that form a 2x2 square or a 2x3/3x2 rectangle.
            ys = [p[0] for p in obj]
            xs = [p[1] for p in obj]
